#include "CUDACore/cudastdAlgorithm.h"
#include <algorithm>
#include <iostream>
#include <iterator>
#include <vector>


// The following comment is generated by an LLM. 
/**
 * Tests binary find functionality with duplicate values in a sorted vector.
  * Performs a binary search for a specific value within a sorted range of elements.
 *
 * @param first beginning of the search range
 * @param last end of the search range
 * @param value to be searched
 * @return iterator pointing to the first element not less than the specified value
  * Finds the upper bound of a value within a sorted range of elements.
 *
 * @param first beginning of the search range
 * @param last end of the search range
 * @param value to be searched
 * @return iterator pointing to the first element greater than the specified value
  * Searches for an element within a sorted range using binary search algorithm.
 *
 * @param first beginning of the search range
 * @param last end of the search range
 * @param value to be searched
 * @return iterator pointing to the element if found, otherwise end of the range
 */ 
void testBinaryFind() {
  std::vector<int> data = {1, 1, 2, 3, 3, 3, 3, 4, 4, 4, 5, 5, 6};

  auto lower = hip_std::lower_bound(data.begin(), data.end(), 4);
  auto upper = hip_std::upper_bound(data.begin(), data.end(), 4);

  std::copy(lower, upper, std::ostream_iterator<int>(std::cout, " "));

  std::cout << '\n';

  // classic binary search, returning a value only if it is present

  data = {1, 2, 4, 6, 9, 10};

  auto test = [&](auto v) {
    auto it = hip_std::binary_find(data.cbegin(), data.cend(), v);

    if (it != data.cend())
      std::cout << *it << " found at index " << std::distance(data.cbegin(), it) << std::endl;
    else
      std::cout << v << " non found" << std::endl;
  };

  test(4);
  test(5);
}

int main() { testBinaryFind(); }
